function prism_draw_map(g) {
    var wall = g.biome.glyph_wall;
    var floor_g = g.biome.glyph_floor;
    var stairs_g = g.biome.glyph_stairs;

    for (var y = 0; y < g.map_h; y++) {
        for (var x = 0; x < g.map_w; x++) {
            var t = ds_grid_get(g.map, x, y);

            var glyph = floor_g;
            if (t == PrismTile.WALL) glyph = wall;
            else if (t == PrismTile.STAIRS) glyph = stairs_g;

            draw_text(x * PRISM_TILE, y * PRISM_TILE, glyph);
        }
    }
}

function prism_draw_entities(g) {
    var n = array_length_1d(g.entities);
    for (var i = 0; i < n; i++) {
        var e = g.entities[i];
        if (!is_struct(e)) continue;
        if (!e.alive) continue;

        draw_text(e.pos.x * PRISM_TILE, e.pos.y * PRISM_TILE, e.render.glyph);
    }
}

function prism_draw_ui(g) {
    var px = PRISM_UI_X;
    var py = PRISM_UI_Y;

    draw_text(px, py, g.title);
    py += 22;

