            py += 18;
            draw_text(px, py, "Bamboo: " + string(p.stats.bamboo));
            py += 18;
            draw_text(px, py, "Labyrinth: " + string(p.stats.labyrinth));
            py += 18;
            draw_text(px, py, "Halo: " + string(p.stats.halo));
