function prism_font_create() {
    var f = font_add("Consolas", 18, false, false, 32, 127);
    if (f == -1) f = font_add("Courier New", 18, false, false, 32, 127);
    return f;
}

function prism_arr_push(arr, v) {
    var n = array_length_1d(arr);
    arr[n] = v;
    return arr;
}

function prism_arr_remove_value(arr, v) {
    var out = [];
    var n = array_length_1d(arr);
    var j = 0;

    for (var i = 0; i < n; i++) {
        if (arr[i] != v) {
            out[j] = arr[i];
            j += 1;
        }
    }
    return out;
}

function prism_arr_concat(a, b) {
    var out = a;
    var bn = array_length_1d(b);
    for (var i = 0; i < bn; i++) {
        out = prism_arr_push(out, b[i]);
    }
    return out;
}

