/// Notes:
/// - Axes: Bamboo/Labyrinth/Halo exist; only Bamboo impacts HP in this slice.
/// - Gate Patterns: triples/doubles/straights trigger small “dream logic” events.
/// - Haloic-inspired naming uses chantable syllable chunks (not a copied table). fileciteturn1file2L4-L10

enum PrismTile {
    Floor = 0,
    Wall = 1,
    Stairs = 2,
}

enum PrismPhase {
    Player = 0,
    Enemies = 1,
    World = 2,
    Status = 3,
}

enum PrismMode {
    MaskSelect = 0,
    InRun = 1,
    GameOver = 2,
}

enum PrismFaction {
    Player = 0,
    Hostile = 1,
    Neutral = 2,
}

function prism_clamp_int(v, lo, hi) {
    return clamp(floor(v), lo, hi);
}

function prism_sign_int(v) {
    if (v > 0) return 1;
    if (v < 0) return -1;
    return 0;
}

function prism_key_pressed_any(keys_arr) {
    var n = array_length(keys_arr);
    for (var i = 0; i < n; i++) {
        if (keyboard_check_pressed(keys_arr[i])) return true;
    }
    return false;
}

function prism_log_add(state, msg) {
    if (is_undefined(state) || is_undefined(state.log)) return;
    if (ds_list_size(state.log) >= state.log_max) ds_list_delete(state.log, 0);
    ds_list_add(state.log, msg);
}

function prism_log_last(state) {
    if (ds_list_size(state.log) <= 0) return "";
    return state.log[| ds_list_size(state.log) - 1];
}

function prism_meta_load() {
    var meta = { shards: 0, best_floor: 0, total_runs: 0 };
    var ini_name = "PrismaticLabyrinth.ini";

    if (file_exists(ini_name)) {
        ini_open(ini_name);
        meta.shards = ini_read_real("meta", "shards", 0);
        meta.best_floor = ini_read_real("meta", "best_floor", 0);
        meta.total_runs = ini_read_real("meta", "total_runs", 0);
        ini_close();
    }
    return meta;
}

function prism_meta_save(meta) {
    var ini_name = "PrismaticLabyrinth.ini";
    ini_open(ini_name);
    ini_write_real("meta", "shards", meta.shards);
    ini_write_real("meta", "best_floor", meta.best_floor);
    ini_write_real("meta", "total_runs", meta.total_runs);
    ini_close();
}

function prism_content_build() {
    // New, game-specific content. Not a copy of any external table.
    // Masks are “starting archetypes”.
    return {
        masks: [
            { id: "MASK_ROOTED_BEAST", name: "Rooted Beast", bamboo: 5, labyrinth: 2, halo: 1, hint: "HP-heavy. You endure the dream’s impact." },
            { id: "MASK_DOOR_CARTO",    name: "Door Cartographer", bamboo: 3, labyrinth: 5, halo: 1, hint: "Map-aware. The maze feels less hostile." },
            { id: "MASK_OATHWEAVER",   name: "Oathweaver", bamboo: 3, labyrinth: 2, halo: 5, hint: "Story-heavy. Gate patterns tilt in your favor." },
        ],
        enemies: [
            { id: "ECHO_MOTH",   name: "Echo Moth", glyph: "m", hp: 3 },
            { id: "GLASS_HOUND", name: "Glass Hound", glyph: "h", hp: 4 },
            { id: "FOG_ACOLYTE", name: "Fog Acolyte", glyph: "f", hp: 2 },
        ],
        sigils: [
            { id: "SIGIL_REFRACT", tag: "REFRACT", cooldown: 6, hint: "Heal a little; story pressure shifts." },
        ],
    };
}

function prism_invocation_make(state, tag) {
    // Haloic-inspired: chantable syllable chunks + agglutinative vibe. fileciteturn1file2L4-L10
    // We intentionally do NOT reproduce any letter tables; we just borrow the “phonetic, chant-friendly” idea.
    var roots = [
        "an", "er", "ig", "on", "um",
        "sha", "ken", "sol", "rad", "tir",
        "wun", "yar", "ing", "cha", "thu",
        "man", "lif", "ber", "dag", "gal",
        "nau", "per"
    ];
    var suffixes = ["el", "im", "eth", "ai", "or", "uz"];

    var a = roots[irandom(array_length(roots) - 1)];
    var b = roots[irandom(array_length(roots) - 1)];
    var c = roots[irandom(array_length(roots) - 1)];

    // bias by tag
    if (tag == "REFRACT") {
        a = choose("sol", "ken", "an", a);
        c = choose("um", "lif", c);
    }

    var sfx = suffixes[irandom(array_length(suffixes) - 1)];

    var word = string_upper(string_copy(a, 1, 1)) + string_copy(a, 2, string_length(a) - 1);
    word += "-" + b;
    if (irandom(1) == 1) word += "-" + c;
    word += "-" + sfx;

    return word;
}

function prism_gate_roll_axes() {
    return { b: irandom_range(1, 6), l: irandom_range(1, 6), h: irandom_range(1, 6) };
}

function prism_gate_analyze(b, l, h) {
    // Pattern logic inspired by your “Patterns and Gates” framing (triples/doubles/straights). fileciteturn1file14L3-L13
    var is_triple = (b == l) && (l == h);

    var is_double = (!is_triple) && ((b == l) || (b == h) || (l == h));

    // straight: three distinct consecutive values
    var a0 = b, a1 = l, a2 = h;

    // sort 3 values
    var x = min(a0, min(a1, a2));
    var z = max(a0, max(a1, a2));
    var y = (a0 + a1 + a2) - x - z;

    var is_distinct = (x != y) && (y != z) && (x != z);
    var is_straight = is_distinct && (x + 1 == y) && (y + 1 == z);

    var odd_axis = "";
    if (is_double) {
        // Find the odd die out (“one axis shouts”) conceptually. fileciteturn1file14L9-L10
        if (b == l) odd_axis = "Halo";
        else if (b == h) odd_axis = "Labyrinth";
        else odd_axis = "Bamboo";
    }

    return {
        is_triple: is_triple,
        is_double: is_double,
        is_straight: is_straight,
        straight_low: is_straight && (x <= 2),
        straight_high: is_straight && (z >= 5),
        odd_axis: odd_axis,
        sorted_low: x,
        sorted_mid: y,
        sorted_high: z,
    };
}

function prism_voice_pick() {
    // The “Quadratic Core” cast as abstract “voices”. fileciteturn1file1L34-L39
    return choose("Solaris", "Lirael", "Morgana", "GG");
}

function prism_voice_line(voice, topic) {
    // New original lines (not copied).
    if (voice == "Solaris") {
        if (topic == "TRIPLE") return "SOLARIS: Triple resonance detected. 1) Observe. 2) Adapt. 3) Proceed.";
        if (topic == "DOUBLE") return "SOLARIS: Two values converge; the outlier is your constraint variable.";
        if (topic == "STRAIGHT") return "SOLARIS: Sequential drift. Expect phase transition behavior.";
        if (topic == "DEATH") return "SOLARIS: End-state reached. Archive the run; keep the lesson.";
        return "SOLARIS: Maintain clarity. The maze rewards coherent intent.";
    }

    if (voice == "Lirael") {
        if (topic == "TRIPLE") return "LIRAEL: Three bells in the fog—your myth answers in chorus.";
        if (topic == "DOUBLE") return "LIRAEL: Two hands clasp; the third trembles. Touch it gently.";
        if (topic == "STRAIGHT") return "LIRAEL: A staircase of numbers—your steps remember how to rise.";
        if (topic == "DEATH") return "LIRAEL: Sleep now. The thread is not cut—only folded.";
        return "LIRAEL: I keep the shimmer of your choices like dew in a jar.";
    }

    if (voice == "Morgana") {
        if (topic == "TRIPLE") return "MORGANA: Power clusters. Spend it with discipline—or it spends you.";
        if (topic == "DOUBLE") return "MORGANA: The odd axis is the boundary. Do not bargain past it.";
        if (topic == "STRAIGHT") return "MORGANA: Momentum is a blade. Aim it, or bleed on it.";
        if (topic == "DEATH") return "MORGANA: A throne rejects the unready. Return sharper.";
        return "MORGANA: Say no to false doors. Your will is your lock.";
    }

    // GG
    if (topic == "TRIPLE") return "GG: yooo triple! the labyrinth just did a backflip.";
    if (topic == "DOUBLE") return "GG: two match, one screams. guess which one’s the drama queen?";
    if (topic == "STRAIGHT") return "GG: straight line in a labyrinth?? illegal. love it.";
    if (topic == "DEATH") return "GG: respawn vibes. hydrate and press R, champ.";
    return "GG: if it’s weird, it’s probably working. maybe.";
}

function prism_entity_make(id, kind, x, y, glyph, faction, bamboo, labyrinth, halo, hp, hp_max) {
    return {
        id: id,
        kind: kind,
        x: x,
        y: y,
        glyph: glyph,
        faction: faction,
        bamboo: bamboo,
        labyrinth: labyrinth,
        halo: halo,
        hp: hp,
        hp_max: hp_max,
        alive: true,
        sigil_cd: 0,
    };
}

function prism_entities_clear(state) {
    if (!is_undefined(state.entities)) {
        ds_list_destroy(state.entities);
    }
    state.entities = ds_list_create();
    state.next_entity_id = 1;
    state.player_id = -1;
}

function prism_entity_add(state, ent) {
    ds_list_add(state.entities, ent);
    return ent.id;
}

function prism_entity_by_id(state, id) {
    var n = ds_list_size(state.entities);
    for (var i = 0; i < n; i++) {
        var e = state.entities[| i];
        if (e.id == id) return e;
    }
    return undefined;
}

function prism_entity_index_by_id(state, id) {
    var n = ds_list_size(state.entities);
    for (var i = 0; i < n; i++) {
        var e = state.entities[| i];
        if (e.id == id) return i;
    }
    return -1;
}

function prism_entity_at_xy(state, x, y) {
    var n = ds_list_size(state.entities);
    for (var i = 0; i < n; i++) {
        var e = state.entities[| i];
        if (e.alive && e.x == x && e.y == y) return e;
    }
    return undefined;
}

function prism_is_inside(state, x, y) {
    return (x >= 0) && (y >= 0) && (x < state.map_w) && (y < state.map_h);
}

function prism_tile_is_walkable(state, x, y) {
    if (!prism_is_inside(state, x, y)) return false;
    var t = state.tiles[# x, y];
    return (t == PrismTile.Floor) || (t == PrismTile.Stairs);
}

function prism_damage_for(attacker) {
    // Keep tiny for slice. Later: scale with axes and sigils.
    return 1 + floor(attacker.bamboo / 4);
}

function prism_kill_entity(state, victim) {
    victim.alive = false;
    if (victim.faction == PrismFaction.Hostile) {
        state.kills += 1;
        state.run_shards += 1;
    }
}

function prism_melee(state, attacker, defender) {
    var dmg = prism_damage_for(attacker);
    defender.hp -= dmg;

    prism_log_add(state, attacker.glyph + " hits " + defender.glyph + " for " + string(dmg) + ".");

    if (defender.hp <= 0) {
        prism_log_add(state, defender.glyph + " dissolves into glittering dust.");
        prism_kill_entity(state, defender);
    }
}

function prism_try_move_or_attack(state, actor, dx, dy) {
    var nx = actor.x + dx;
    var ny = actor.y + dy;

    if (!prism_is_inside(state, nx, ny)) {
        prism_log_add(state, "The edge of the dream refuses you.");
        return false;
    }

    if (!prism_tile_is_walkable(state, nx, ny)) {
        prism_log_add(state, "Wall: cold, soft, absolute.");
        return false;
    }

    var other = prism_entity_at_xy(state, nx, ny);
    if (!is_undefined(other)) {
        if (other.faction != actor.faction) {
            prism_melee(state, actor, other);
            return true;
        }
        return false;
    }

    actor.x = nx;
    actor.y = ny;

    // Stairs check for player
    if (actor.id == state.player_id) {
        if (state.tiles[# nx, ny] == PrismTile.Stairs) {
            prism_log_add(state, "You step through the Threshold. The map forgets itself.");
            state.pending_next_floor = true;
        }
    }
    return true;
}

function prism_rooms_intersect(a, b) {
    return !(a.x2 < b.x1 || a.x1 > b.x2 || a.y2 < b.y1 || a.y1 > b.y2);
}

function prism_carve_room(state, r) {
    for (var y = r.y1; y <= r.y2; y++) {
        for (var x = r.x1; x <= r.x2; x++) {
            if (prism_is_inside(state, x, y)) state.tiles[# x, y] = PrismTile.Floor;
        }
    }
}

function prism_carve_h_corridor(state, x1, x2, y) {
    var a = min(x1, x2);
    var b = max(x1, x2);
    for (var x = a; x <= b; x++) {
        if (prism_is_inside(state, x, y)) state.tiles[# x, y] = PrismTile.Floor;
    }
}

function prism_carve_v_corridor(state, y1, y2, x) {
    var a = min(y1, y2);
    var b = max(y1, y2);
    for (var y = a; y <= b; y++) {
        if (prism_is_inside(state, x, y)) state.tiles[# x, y] = PrismTile.Floor;
    }
}

function prism_find_random_floor(state, avoid_x, avoid_y, avoid_r) {
    var tries = 2000;
    while (tries-- > 0) {
        var x = irandom(state.map_w - 1);
        var y = irandom(state.map_h - 1);
        if (!prism_tile_is_walkable(state, x, y)) continue;

        var dist = abs(x - avoid_x) + abs(y - avoid_y);
        if (dist < avoid_r) continue;

        if (!is_undefined(prism_entity_at_xy(state, x, y))) continue;

        return { x: x, y: y };
    }
    return { x: avoid_x, y: avoid_y };
}

function prism_generate_floor(state) {
    // Reset map
    if (!is_undefined(state.tiles)) ds_grid_destroy(state.tiles);
    state.tiles = ds_grid_create(state.map_w, state.map_h);

    for (var y = 0; y < state.map_h; y++) {
        for (var x = 0; x < state.map_w; x++) {
            state.tiles[# x, y] = PrismTile.Wall;
        }
    }

    prism_entities_clear(state);

    var rooms = [];
    var max_rooms = 10 + min(6, state.floor_index);
    var attempts = 120;

    while (array_length(rooms) < max_rooms && attempts-- > 0) {
        var rw = irandom_range(5, 11);
        var rh = irandom_range(5, 9);
        var rx = irandom_range(2, state.map_w - rw - 3);
        var ry = irandom_range(2, state.map_h - rh - 3);

        var r = {
            x1: rx, y1: ry,
            x2: rx + rw, y2: ry + rh,
            cx: rx + floor(rw / 2),
            cy: ry + floor(rh / 2),
        };

        // padding for intersections
        var rp = {
            x1: r.x1 - 1, y1: r.y1 - 1,
            x2: r.x2 + 1, y2: r.y2 + 1,
        };

        var ok = true;
        for (var i = 0; i < array_length(rooms); i++) {
            var o = rooms[i];
            var op = { x1: o.x1 - 1, y1: o.y1 - 1, x2: o.x2 + 1, y2: o.y2 + 1 };
            if (prism_rooms_intersect(rp, op)) { ok = false; break; }
        }
        if (!ok) continue;

        prism_carve_room(state, r);

        if (array_length(rooms) > 0) {
            var prev = rooms[array_length(rooms) - 1];

            // L-corridor
            if (irandom(1) == 0) {
                prism_carve_h_corridor(state, prev.cx, r.cx, prev.cy);
                prism_carve_v_corridor(state, prev.cy, r.cy, r.cx);
            } else {
                prism_carve_v_corridor(state, prev.cy, r.cy, prev.cx);
                prism_carve_h_corridor(state, prev.cx, r.cx, r.cy);
            }
        }

        array_push(rooms, r);
    }

    if (array_length(rooms) <= 0) {
        // fallback
        var mid = { x1: 4, y1: 4, x2: state.map_w - 5, y2: state.map_h - 5, cx: floor(state.map_w/2), cy: floor(state.map_h/2) };
        prism_carve_room(state, mid);
        rooms = [mid];
    }

    var start_room = rooms[0];
    var end_room = rooms[array_length(rooms) - 1];

    // Place stairs
    state.tiles[# end_room.cx, end_room.cy] = PrismTile.Stairs;
    state.stairs_x = end_room.cx;
    state.stairs_y = end_room.cy;

    // Spawn player from selected mask
    var mask = state.selected_mask;
    var bamboo = mask.bamboo;
    var labyrinth = mask.labyrinth;
    var halo = mask.halo;

    // Bamboo drives HP only for slice
    var hp_max = 8 + bamboo * 2;

    var pid = state.next_entity_id++;
    var p = prism_entity_make(pid, "player", start_room.cx, start_room.cy, "@", PrismFaction.Player, bamboo, labyrinth, halo, hp_max, hp_max);
    p.sigil_name = prism_invocation_make(state, "REFRACT");
    prism_entity_add(state, p);
    state.player_id = pid;

    // Spawn enemies
    var enemy_count = 3 + min(5, state.floor_index);
    for (var k = 0; k < enemy_count; k++) {
        var spot = prism_find_random_floor(state, start_room.cx, start_room.cy, 8);
        var proto = state.content.enemies[irandom(array_length(state.content.enemies) - 1)];

        var eid = state.next_entity_id++;
        var e = prism_entity_make(eid, "enemy", spot.x, spot.y, proto.glyph, PrismFaction.Hostile, 1, 1, 1, proto.hp, proto.hp);
        e.enemy_name = proto.name;
        prism_entity_add(state, e);
    }

    state.phase = PrismPhase.Player;
    state.pending_next_floor = false;

    prism_log_add(state, "BOOT: Empty Throne protocol engaged.");
    prism_log_add(state, "Mask: " + mask.name + ". Floor " + string(state.floor_index) + " spawns.");
}

function prism_state_create() {
    var state = {
        tile_size: 16,
        map_w: 60,
        map_h: 34,

        mode: PrismMode.MaskSelect,
        phase: PrismPhase.Player,

        floor_index: 1,
        turns: 0,
        kills: 0,
        story_pressure: 0,
        pending_next_floor: false,

        tiles: undefined,

        entities: ds_list_create(),
        next_entity_id: 1,
        player_id: -1,

        log: ds_list_create(),
        log_max: 9,

        content: prism_content_build(),
        selected_mask: undefined,

        meta: prism_meta_load(),
        run_shards: 0,
    };

    prism_log_add(state, "Root user: awake.");
    prism_log_add(state, "Choose a mask (1/2/3).");
    return state;
}

function prism_state_destroy(state) {
    if (!is_undefined(state.tiles)) ds_grid_destroy(state.tiles);
    if (!is_undefined(state.entities)) ds_list_destroy(state.entities);
    if (!is_undefined(state.log)) ds_list_destroy(state.log);
}

function prism_begin_run(state) {
    state.meta.total_runs += 1;
    prism_meta_save(state.meta);

    state.floor_index = 1;
    state.turns = 0;
    state.kills = 0;
    state.story_pressure = 0;
    state.run_shards = 0;

    prism_generate_floor(state);

    state.mode = PrismMode.InRun;
    prism_log_add(state, "DESCENT: You fall gently into geometry.");
}

function prism_end_run(state) {
    state.mode = PrismMode.GameOver;

    state.meta.shards += state.run_shards;
    state.meta.best_floor = max(state.meta.best_floor, state.floor_index);
    prism_meta_save(state.meta);

    var v = prism_voice_pick();
    prism_log_add(state, prism_voice_line(v, "DEATH"));
    prism_log_add(state, "Run over. Shards gained: " + string(state.run_shards) + ". Press R.");
}

function prism_apply_gate_event(state, axes, analysis, context) {
    var v = prism_voice_pick();

    var msg = "GATE(" + context + "): B" + string(axes.b) + " L" + string(axes.l) + " H" + string(axes.h) + ".";
    prism_log_add(state, msg);

    if (analysis.is_triple) {
        prism_log_add(state, prism_voice_line(v, "TRIPLE"));

        // Unique triple event: small boon or twist
        var pick = irandom(2);
        var p = prism_entity_by_id(state, state.player_id);

        if (pick == 0) {
            var heal = 2 + irandom(1);
            p.hp = min(p.hp_max, p.hp + heal);
            prism_log_add(state, "Resonance refracts into warmth. +" + string(heal) + " HP.");
        } else if (pick == 1) {
            state.story_pressure = max(0, state.story_pressure - 1);
            prism_log_add(state, "A hymn quiets the walls. Story pressure eases.");
        } else {
            // spawn an echo enemy
            var spot = prism_find_random_floor(state, p.x, p.y, 10);
            var proto = choose(state.content.enemies[0], state.content.enemies[2]);
            var eid = state.next_entity_id++;
            var e = prism_entity_make(eid, "enemy", spot.x, spot.y, proto.glyph, PrismFaction.Hostile, 1, 1, 1, proto.hp, proto.hp);
            e.enemy_name = proto.name;
            prism_entity_add(state, e);
            prism_log_add(state, "A new echo condenses in the fog.");
        }
        return;
    }

    if (analysis.is_double) {
        prism_log_add(state, prism_voice_line(v, "DOUBLE"));
        prism_log_add(state, "One axis speaks loudest: " + analysis.odd_axis + ".");
        // tiny nudge:
        state.story_pressure += 1;
        return;
    }

    if (analysis.is_straight) {
        prism_log_add(state, prism_voice_line(v, "STRAIGHT"));

        if (analysis.straight_low) {
            state.story_pressure += 2;
            prism_log_add(state, "The dream tightens its frame. Pressure rises.");
        } else if (analysis.straight_high) {
            state.story_pressure = max(0, state.story_pressure - 1);
            var p2 = prism_entity_by_id(state, state.player_id);
            p2.hp = min(p2.hp_max, p2.hp + 1);
            prism_log_add(state, "The maze exhales. +1 HP.");
        } else {
            prism_log_add(state, "A turning sequence passes through you and moves on.");
        }
        return;
    }
}

function prism_world_pulse(state) {
    state.turns += 1;

    // light “dream logic”
    if (irandom(10) < min(4, state.story_pressure)) {
        prism_log_add(state, "PULSE: Doors remember different hinges.");
    }

    // Gate roll sometimes
    if (irandom(7) == 0) {
        var axes = prism_gate_roll_axes();
        var analysis = prism_gate_analyze(axes.b, axes.l, axes.h);
        prism_apply_gate_event(state, axes, analysis, "pulse");
    }

    // Echo spawn chance scales slightly with story_pressure
    var p = prism_entity_by_id(state, state.player_id);
    var spawn_roll = irandom(100);
    var spawn_chance = 2 + state.story_pressure; // %
    if (spawn_roll < spawn_chance) {
        var spot = prism_find_random_floor(state, p.x, p.y, 12);
        var proto = state.content.enemies[irandom(array_length(state.content.enemies) - 1)];
        var eid = state.next_entity_id++;
        var e = prism_entity_make(eid, "enemy", spot.x, spot.y, proto.glyph, PrismFaction.Hostile, 1, 1, 1, proto.hp, proto.hp);
        e.enemy_name = proto.name;
        prism_entity_add(state, e);
        prism_log_add(state, "PULSE: An echo spawns at the edge of sight.");
    }
}

function prism_status_tick(state) {
    var p = prism_entity_by_id(state, state.player_id);
    if (p.sigil_cd > 0) p.sigil_cd -= 1;

    // remove dead entities
    for (var i = ds_list_size(state.entities) - 1; i >= 0; i--) {
        var e = state.entities[| i];
        if (!e.alive) ds_list_delete(state.entities, i);
    }
}

function prism_enemy_take_turn(state, enemy) {
    var p = prism_entity_by_id(state, state.player_id);

    var dx = p.x - enemy.x;
    var dy = p.y - enemy.y;

    // adjacent => attack
    if (abs(dx) + abs(dy) == 1) {
        prism_melee(state, enemy, p);
        return;
    }

    // greedy chase
    var step_x = prism_sign_int(dx);
    var step_y = prism_sign_int(dy);

    var moved = false;

    // prefer axis with bigger distance
    if (abs(dx) >= abs(dy)) {
        if (step_x != 0) moved = prism_try_move_or_attack(state, enemy, step_x, 0);
        if (!moved && step_y != 0) moved = prism_try_move_or_attack(state, enemy, 0, step_y);
    } else {
        if (step_y != 0) moved = prism_try_move_or_attack(state, enemy, 0, step_y);
        if (!moved && step_x != 0) moved = prism_try_move_or_attack(state, enemy, step_x, 0);
    }

    // if stuck, jitter
    if (!moved && irandom(3) == 0) {
        var jx = choose(-1, 0, 1);
        var jy = choose(-1, 0, 1);
        if (abs(jx) + abs(jy) == 1) prism_try_move_or_attack(state, enemy, jx, jy);
    }
}

function prism_cast_refraction(state) {
    var p = prism_entity_by_id(state, state.player_id);
    if (p.sigil_cd > 0) {
        prism_log_add(state, "Sigil cooling down (" + string(p.sigil_cd) + ").");
        return false;
    }

    p.sigil_cd = state.content.sigils[0].cooldown;

    var heal = 2;
    p.hp = min(p.hp_max, p.hp + heal);

    // Small story-pressure drift
    state.story_pressure = max(0, state.story_pressure - 1);

    prism_log_add(state, "Cast: " + p.sigil_name + " (+" + string(heal) + " HP).");
    return true;
}

function prism_player_input(state) {
    var p = prism_entity_by_id(state, state.player_id);
    if (is_undefined(p)) return;

    var acted = false;

    if (keyboard_check_pressed(ord("C"))) {
        acted = prism_cast_refraction(state);
    } else if (keyboard_check_pressed(vk_space)) {
        prism_log_add(state, "You wait. The fog counts your breaths.");
        acted = true;
    } else {
        var dx = 0, dy = 0;

        if (keyboard_check_pressed(vk_left) || keyboard_check_pressed(ord("A"))) dx = -1;
        else if (keyboard_check_pressed(vk_right) || keyboard_check_pressed(ord("D"))) dx = 1;
        else if (keyboard_check_pressed(vk_up) || keyboard_check_pressed(ord("W"))) dy = -1;
        else if (keyboard_check_pressed(vk_down) || keyboard_check_pressed(ord("S"))) dy = 1;

        if (dx != 0 || dy != 0) acted = prism_try_move_or_attack(state, p, dx, dy);
    }

    if (!acted) return;

    if (p.hp <= 0) {
        prism_end_run(state);
        return;
    }

    state.phase = PrismPhase.Enemies;
}

function prism_step(state) {
    if (state.mode == PrismMode.MaskSelect) {
        if (keyboard_check_pressed(ord("1"))) state.selected_mask = state.content.masks[0];
        if (keyboard_check_pressed(ord("2"))) state.selected_mask = state.content.masks[1];
        if (keyboard_check_pressed(ord("3"))) state.selected_mask = state.content.masks[2];

        if (!is_undefined(state.selected_mask)) {
            prism_begin_run(state);
        }
        return;
    }

    if (state.mode == PrismMode.GameOver) {
        if (keyboard_check_pressed(ord("R"))) {
            // reset to selection
            state.mode = PrismMode.MaskSelect;
            state.selected_mask = undefined;
            state.phase = PrismPhase.Player;
            state.floor_index = 1;
            state.turns = 0;
            state.kills = 0;
            state.story_pressure = 0;
            state.run_shards = 0;

            prism_log_add(state, "Root user: awake.");
            prism_log_add(state, "Choose a mask (1/2/3).");
        }
        return;
    }

    // In run
    if (state.phase == PrismPhase.Player) {
        prism_player_input(state);
        return;
    }

    if (state.phase == PrismPhase.Enemies) {
        var n = ds_list_size(state.entities);
        for (var i = 0; i < n; i++) {
            var e = state.entities[| i];
            if (!e.alive) continue;
            if (e.faction == PrismFaction.Hostile) prism_enemy_take_turn(state, e);
        }

        var p = prism_entity_by_id(state, state.player_id);
        if (p.hp <= 0) {
            prism_end_run(state);
            return;
        }

        state.phase = PrismPhase.World;
    }

    if (state.phase == PrismPhase.World) {
        prism_world_pulse(state);
        state.phase = PrismPhase.Status;
    }

    if (state.phase == PrismPhase.Status) {
        prism_status_tick(state);

        // next floor if requested
        if (state.pending_next_floor) {
            state.floor_index += 1;

            // award shards for descent
            state.run_shards += 2;
            state.meta.best_floor = max(state.meta.best_floor, state.floor_index);
            prism_meta_save(state.meta);

            prism_generate_floor(state);
        }

        state.phase = PrismPhase.Player;
    }
}

function prism_tile_glyph(t) {
    if (t == PrismTile.Wall) return "#";
    if (t == PrismTile.Floor) return ".";
    if (t == PrismTile.Stairs) return ">";
    return "?";
}

function prism_draw(state) {
    draw_set_color(c_white);

    // background
    draw_clear(c_black);

    var map_px_w = state.map_w * state.tile_size;
    var map_px_h = state.map_h * state.tile_size;
    var ox = floor((room_width - map_px_w) * 0.5);
    var oy = 16;

    // tiles
    for (var y = 0; y < state.map_h; y++) {
        for (var x = 0; x < state.map_w; x++) {
            var g = prism_tile_glyph(state.tiles[# x, y]);
            draw_text(ox + x * state.tile_size, oy + y * state.tile_size, g);
        }
    }

    // entities
    var n = ds_list_size(state.entities);
    for (var i = 0; i < n; i++) {
        var e = state.entities[| i];
        if (!e.alive) continue;
        draw_text(ox + e.x * state.tile_size, oy + e.y * state.tile_size, e.glyph);
    }

    // UI
    var ui_y = oy + map_px_h + 8;

    if (state.mode == PrismMode.MaskSelect) {
        draw_text(16, 16, "PRISMATIC LABYRINTH: Empty Throne Dreamware");
        draw_text(16, 40, "Choose a Mask:");
        for (var i2 = 0; i2 < array_length(state.content.masks); i2++) {
            var m = state.content.masks[i2];
            var line = string(i2 + 1) + ") " + m.name + "  (B" + string(m.bamboo) + " L" + string(m.labyrinth) + " H" + string(m.halo) + ")";
            draw_text(16, 64 + i2 * 18, line);
            draw_text(16, 80 + i2 * 18, "   " + m.hint);
        }
        draw_text(16, 140, "Meta shards: " + string(state.meta.shards) + " | Best floor: " + string(state.meta.best_floor));
        return;
    }

    if (state.mode == PrismMode.GameOver) {
        draw_text(16, 16, "RUN OVER");
        draw_text(16, 40, "Floor reached: " + string(state.floor_index));
        draw_text(16, 58, "Kills: " + string(state.kills));
        draw_text(16, 76, "Shards gained: " + string(state.run_shards));
        draw_text(16, 100, "Press R to restart.");
        return;
    }

    var p = prism_entity_by_id(state, state.player_id);
    var phase_name = (state.phase == PrismPhase.Player) ? "PLAYER" :
                     (state.phase == PrismPhase.Enemies) ? "ENEMIES" :
                     (state.phase == PrismPhase.World) ? "WORLD" : "STATUS";

    draw_text(16, ui_y, "Floor " + string(state.floor_index) + " | Turn " + string(state.turns) + " | Phase " + phase_name);
    draw_text(16, ui_y + 18, "HP " + string(p.hp) + "/" + string(p.hp_max) +
                              " | Bamboo " + string(p.bamboo) +
                              " | Labyrinth " + string(p.labyrinth) +
                              " | Halo " + string(p.halo) +
                              " | Pressure " + string(state.story_pressure));

    draw_text(16, ui_y + 36, "Sigil: " + p.sigil_name + " (C) cd=" + string(p.sigil_cd));

    draw_text(16, ui_y + 60, "Run shards: " + string(state.run_shards) + " | Meta shards: " + string(state.meta.shards));

    // log lines
    var lx = 16;
    var ly = ui_y + 86;
    var lines = ds_list_size(state.log);
    var start = max(0, lines - state.log_max);

    draw_text(lx, ly - 18, "LOG:");
    var row = 0;
    for (var i3 = start; i3 < lines; i3++) {
        draw_text(lx, ly + row * 16, state.log[| i3]);
        row += 1;
    }
}

